def lucas(n):
    if n == 0:
        return 2
    if n == 1:
        return 1
    a, b = 2, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

l100 = lucas(100)
print(f"L_100: {l100}")

S = {0, 1, 3, 5, 13}
differences = set()
for x in S:
    for y in S:
        differences.add(x - y)

print(f"Differences generated by S: {sorted(list(differences))}")
